    $('editor').addEventListener('cancel',event=>{if(formOpen){event.preventDefault();event.stopImmediatePropagation();}},true);
    function meetingContext(){const c=context();return c.profile.id+'|'+c.account+'|'+c.generation+'|'+c.calendars.map(cal=>cal.id).join('|');}
    function filterCalendars(){const query=$('profile-calendar-search').value.toLowerCase();$('profile-meetings-calendars').querySelectorAll('label').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(query));}
    function calendars(){const c=context(),key=c.profile.id+'|'+c.calendars.map(cal=>cal.id).join('|');if(key!==linkedKey){linkedKey=key;selected=c.calendars.map(cal=>cal.id);}$('profile-meetings-calendars').innerHTML=c.calendars.map(cal=>'<label class="calendar-picker-option"><input type="checkbox" data-profile-calendar="'+esc(cal.id)+'"'+(selected.includes(cal.id)?' checked':'')+'><span class="calendar-option-name" title="'+esc(cal.summaryOverride||cal.summary||cal.id)+'">'+esc(cal.summaryOverride||cal.summary||cal.id)+'</span></label>').join('');$('profile-meetings-selected').textContent=selected.length+' selected';$('profile-meetings-calendars').querySelectorAll('input').forEach(el=>el.onchange=()=>{selected=[...$('profile-meetings-calendars').querySelectorAll('input:checked')].map(el=>el.dataset.profileCalendar);$('profile-meetings-selected').textContent=selected.length+' selected';pageSize=50;renderMeetings();});filterCalendars();}
