    async function load(refresh=false){const c=context(),token=++generation,signature=meetingContext(),from=$('profile-meetings-from').value,to=$('profile-meetings-to').value;try{if(!c.reader)throw new Error('Connect Google Calendar to load meetings.');V.bounds(from,to,c.profile.tz);if(!c.calendars.length){$('event-list').innerHTML='<p class="muted">Link a calendar in Availability calendars to manage this person’s meetings.</p>';return;}await opts.beforeRead();if(token!==generation||signature!==meetingContext())return;const fresh=context(),snapshot=cache.snapshot(c.account,from,to);if(snapshot&&snapshot.calendars.map(cal=>cal.id).join('|')!==fresh.calendars.map(cal=>cal.id).join('|'))refresh=true;cache.reconcile(fresh.calendars);calendars();await cache.load({account:c.account,from,to,calendars:fresh.calendars,reader:c.reader,refresh,onUpdate:()=>{if(token===generation&&signature===meetingContext()&&$('editor').open)renderMeetings();}});}catch(error){if(token===generation)$('profile-events-status').textContent=error.message;}}
